#!/usr/bin/env node
/**
 * @file ASVS 5.0.0 L1+L2 requirement-level self-assessment as code (ADR-0028).
 * @module scripts
 *
 * Inputs (source of truth):
 *   docs/security/asvs/asvs-5.0.0-l1-l2.json — canonical requirement ids/levels from the OWASP CSV
 *   docs/security/asvs/assessment.json       — one entry per id: status, evidence paths, note
 * Output (generated, do not edit): docs/security/ASVS_L2_ASSESSMENT.md
 *
 *   node scripts/asvs-report.mjs           validate, then render the Markdown
 *   node scripts/asvs-report.mjs --check   validate and fail if the Markdown is stale
 *
 * Validation (fails closed): every canonical id assessed exactly once, no unknown ids, a known
 * status, evidence paths that exist, I+T entries citing at least one test file, a note for every
 * entry. ASSESSMENT_JSON may point at another file (tests use this to prove the checks fire).
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const ROOT = resolve(import.meta.dirname, '..');
const CANON = resolve(ROOT, 'docs/security/asvs/asvs-5.0.0-l1-l2.json');
const ASSESS = process.env.ASSESSMENT_JSON ? resolve(process.env.ASSESSMENT_JSON) : resolve(ROOT, 'docs/security/asvs/assessment.json');
const OUT = resolve(ROOT, 'docs/security/ASVS_L2_ASSESSMENT.md');
const STATUSES = ['I+T', 'I', 'P', 'O', 'ENV', 'N/A'];
const TEST_FILE = /(\.test\.ts|\.spec\.ts)$/;

/** Validates the assessment; returns a list of problems (empty = valid). */
export function validate(canon, assess) {
  const problems = [];
  const ids = new Set(canon.requirements.map((r) => r.id));
  const seen = new Set();
  for (const r of assess.requirements) {
    if (!ids.has(r.id)) problems.push(`${r.id}: not an ASVS 5.0.0 L1/L2 requirement`);
    if (seen.has(r.id)) problems.push(`${r.id}: assessed twice`);
    seen.add(r.id);
    if (!STATUSES.includes(r.status)) problems.push(`${r.id}: unknown status ${r.status}`);
    if (!r.note || r.note.length < 10) problems.push(`${r.id}: note missing`);
    for (const e of r.evidence ?? []) if (!existsSync(resolve(ROOT, e))) problems.push(`${r.id}: evidence not found ${e}`);
    if (r.status === 'I+T' && !(r.evidence ?? []).some((e) => TEST_FILE.test(e))) problems.push(`${r.id}: I+T without a test file`);
    if (['I', 'P'].includes(r.status) && !(r.evidence ?? []).length) problems.push(`${r.id}: ${r.status} without evidence`);
  }
  for (const id of ids) if (!seen.has(id)) problems.push(`${id}: not assessed`);
  return problems;
}

/** Renders the Markdown report. */
export function render(canon, assess) {
  const byId = new Map(assess.requirements.map((r) => [r.id, r]));
  const chapters = [];
  for (const r of canon.requirements) {
    const ch = r.id.split('.')[0];
    let c = chapters.find((x) => x.id === ch);
    if (!c) chapters.push((c = { id: ch, name: r.chapter, rows: [] }));
    c.rows.push({ ...r, ...byId.get(r.id) });
  }
  const count = (rows) => Object.fromEntries(STATUSES.map((s) => [s, rows.filter((r) => r.status === s).length]));
  const all = count(canon.requirements.map((r) => byId.get(r.id)));
  const esc = (s) => String(s).replace(/\|/g, '\\|');
  const lines = [
    `# OWASP ASVS 5.0.0 Level 2 — requirement-level self-assessment (v${assess.assessedVersion})`,
    '',
    '<!-- GENERATED by scripts/asvs-report.mjs from docs/security/asvs/*.json — do not edit. -->',
    '',
    `Owning module: security. Assessed ${assess.assessedAt} by: ${assess.assessor}. **This is not a`,
    'certification or an independent verification** (SEC-OPEN-002); an independent assessor must',
    'verify it. Requirement texts: OWASP ASVS 5.0.0 (CC BY-SA 4.0), source CSV sha256',
    `\`${canon.sourceSha256}\`.`,
    '',
    'Legend: ' + STATUSES.map((s) => `**${s}** ${assess.statuses[s]}`).join(' · ') + '.',
    '',
    `Totals over ${canon.requirements.length} L1+L2 requirements: ` + STATUSES.map((s) => `${s} ${all[s]}`).join(' · ') + '.',
    '',
    '| Chapter | ' + STATUSES.join(' | ') + ' |',
    '| --- | ' + STATUSES.map(() => '---').join(' | ') + ' |',
    ...chapters.map((c) => {
      const k = count(c.rows);
      return `| ${c.id} ${c.name} | ` + STATUSES.map((s) => k[s]).join(' | ') + ' |';
    }),
    '',
    '**Open and partial items:** ' +
      (canon.requirements
        .map((r) => byId.get(r.id))
        .filter((r) => r.status === 'O' || r.status === 'P')
        .map((r) => r.id)
        .join(', ') || 'none') +
      '. **Environment-dependent (verify on the target environment):** ' +
      canon.requirements
        .map((r) => byId.get(r.id))
        .filter((r) => r.status === 'ENV')
        .map((r) => r.id)
        .join(', ') +
      '.',
    '',
  ];
  for (const c of chapters) {
    lines.push(`## ${c.id} ${c.name}`, '', '| Req | L | Status | Evidence | Note |', '| --- | --- | --- | --- | --- |');
    for (const r of c.rows) {
      lines.push(
        `| ${r.id} | ${r.level} | ${r.status} | ${(r.evidence ?? []).map((e) => `\`${e}\``).join('<br>') || '—'} | ${esc(r.note)} |`,
      );
    }
    lines.push('');
  }
  return lines.join('\n');
}

const isMain = process.argv[1] && resolve(process.argv[1]) === resolve(import.meta.filename);
if (isMain) {
  const canon = JSON.parse(readFileSync(CANON, 'utf8'));
  const assess = JSON.parse(readFileSync(ASSESS, 'utf8'));
  const problems = validate(canon, assess);
  if (problems.length) {
    console.error(`ASVS assessment INVALID:\n- ${problems.slice(0, 30).join('\n- ')}`);
    process.exit(1);
  }
  const md = render(canon, assess);
  if (process.argv.includes('--check')) {
    if (!existsSync(OUT) || readFileSync(OUT, 'utf8') !== md) {
      console.error('docs/security/ASVS_L2_ASSESSMENT.md is stale: run `pnpm asvs:render`.');
      process.exit(1);
    }
    console.log(`ASVS assessment OK: ${assess.requirements.length} requirements.`);
  } else {
    writeFileSync(OUT, md);
    console.log(`Rendered ${OUT}`);
  }
}
